import json, hashlib
def load(p):
    d=json.load(open(p)); m={}
    for a in d["artifacts"]:
        for c in a.get("data",{}).get("chunks",[]):
            m[c.get("chunk_index")]=c["content"]
    return m
A=load("kb-results/src-kakunin.json")[17]
B=load("kb-results/src-kakutei.json")[17]
print("len",len(A),len(B),"lines",A.count("\n"),B.count("\n"),"tr",A.count("<tr>"),B.count("<tr>"))
blocks=4096
def h(s): return hashlib.sha256(s.encode()).hexdigest()[:12]
first=None
n=max(len(A),len(B))
for i in range(0,n,blocks):
    if h(A[i:i+blocks])!=h(B[i:i+blocks]):
        first=i; break
print("first differing block at", first)
if first is not None:
    end=min(first+blocks, n)
    # narrow within block
    for j in range(first,end):
        if (A[j:j+1] or "")!=(B[j:j+1] or ""):
            print("approx first differing char", j)
            lo=max(0,j-300)
            print("A window:",repr(A[lo:j+300]))
            print("B window:",repr(B[lo:j+300]))
            break
EOF
